Một người đang ở trên sân thượng ${A}$ của một cái toà nhà nhìn xuống thấy một con đường chạy thẳng đến chân tường. Anh ta nhìn thấy một chiếc xe máy với góc hạ $\widehat{xAC}=31^{\circ}$. Sau $10$ phút lại nhìn thấy xe đó với góc hạ $\widehat{xAD}=63^{\circ}$. Hỏi sau bao nhiêu phút thì xe máy chạy đến chân tường biết vận tốc của xe máy không đổi (làm tròn kết quả đến hàng phần mười).



\choice
{ $4,6$ phút }
   { $4,5$ phút }
     { $4,2$ phút }
    { \True $4,4$ phút }
}{
\begin{tikzpicture}
    \def\hh{6cm}
    \def\aa{5cm}
    \path (0,0) coordinate (B) (0,\hh) coordinate (A) (\aa,0) coordinate (C)
    (3*\aa/5,0) coordinate (D)      (3*\aa/5,\hh) coordinate (x);
        \draw[->] (0,\hh) -- (3*\aa/5,\hh) node[above] {$x$};
    \draw 
(A) pic[draw,angle radius = 6mm] {angle =D--A--x} 
(A) pic[draw,angle radius = 5mm] {angle =C--A--x}   ;
        % Hiển thị nhãn cho các điểm
    \draw (A) node [above] {$A$};
    \draw (B) node [below] {$B$};
    \draw (C) node [below] {$C$};
    \draw (D) node [below right] {$D$};
    % Vẽ tia Ax song song với BC



    % Vẽ hình tứ giác với các điểm A, B, C, D
    \draw (A) -- (B) -- (C) -- (D) -- cycle;

    % Vẽ đường nối A và C bằng nét liền
    \draw (A) -- (C);

    % Vẽ tường mô phòng
    \path[fill=red!30] (B) -- ++(180:5) 
    to[out=100,in=-90] (-4.2,1.5) 
    to[out=100,in=-90] (-3.7,3.5) 
    to[out=100,in=-90] (-2.8,4.8) 
    to[out=120,in=-110] (-2,6) -- (A) -- cycle;

    % Cắt vùng mô phỏng bức tường
    \clip (B) -- ++(180:5) 
    to[out=100,in=-90] (-4.2,1.5) 
    to[out=100,in=-90] (-3.7,3.5) 
    to[out=100,in=-90] (-2.8,4.8) 
    to[out=120,in=-110] (-2,6) -- (A) -- cycle;

    % Tô màu các viên gạch hình chữ nhật
    \fill[pattern=bricks, pattern color=red] (B) -- ++(180:5) 
    to[out=100,in=-90] (-4.2,1.5) 
    to[out=100,in=-90] (-3.7,3.5) 
    to[out=100,in=-90] (-2.8,4.8) 
    to[out=120,in=-110] (-2,6) -- (A) -- cycle;

    % Vẽ lại hình tứ giác và đường nối
    \draw (A)--(B)--(C)--(D)--cycle;
    \draw[dashed] (B)--(A);
    \draw (B)--++(180:5) to[out=100,in=-90](-4.2,1.5) to[out=100,in=-90](-3.7,3.5) to[out=100,in=-90](-2.8,4.8) to[out=120,in=-110](-2,6)--(A)--cycle;


\end{tikzpicture}
}
\loigiai{ 
 Ta có $\widehat{xAC}=\widehat{ACB}=31^{\circ}$ suy ra $BC=AB \cdot \cot{ 31^{\circ} }$ 

Tương tự có $\widehat{xAD}=\widehat{ADB}=63^{\circ}$ suy ra $BD=AB \cdot \cot{ 63^{\circ} }$ 

$DC=BC-BD= AB \cdot \cot{ 31^{\circ} } - AB \cdot \cot{ 63^{\circ} } =AB \left( \cot{ 31^{\circ} }- \cot{ 63^{\circ} } \right)$ 

Vận tốc của xe máy là $v= \dfrac{DC}{10}= \dfrac{AB \left( \cot{ 31^{\circ} }- \cot{ 63^{\circ} } \right) }{10}$

Thời gian xe máy đi từ ${D}$ đến ${B}$ là $t=\dfrac{DB}{v}=\dfrac{AB \cdot \cot{ 63^{\circ} }}{\dfrac{AB \left( \cot{ 31^{\circ} }- \cot{ 63^{\circ} } \right) }{10} }= \dfrac{\cot{ 63^{\circ} \cdot 10 } } { \cot{ 31^{\circ} }- \cot{ 63^{\circ}} } \approx 4,4$ phút 
 }\end{ex}

