L09_C4_B2_36.latex:
\begin{ex}%[9H4C2-5]
\immini[thm]{
Lúc 6h sáng, bạn Anh đi xe đạp từ nhà (điểm ${A}$) đến trường (điểm ${B}$) phải leo và xuống một con dốc (như hình vẽ sau) biết ${AB}=1,0km$, $\widehat{A}=8^{\circ}$, $\widehat{B}=4^{\circ}$. Tính chiều cao ${h}$ của con dốc (theo mét làm tròn đến chữ số hàng đơn vị)
}{
\begin{tikzpicture}

    % Vẽ tam giác ABC
    \coordinate [label=left:A] (A) at (0,0);
    \coordinate [label=right:B] (B) at (8,0);
    \coordinate [label=above:C] (C) at (2,1);

    % Đặt các góc và chiều cao
    \draw (A) -- (B) -- (C) -- cycle;

    % Vẽ chiều cao từ C tới AB
\draw (C) -- (2,0) coordinate (H);
\node[below] at (H) {H};
      % Vẽ dấu vuông tại điểm H
        \draw (2,0) rectangle +(0.1,0.1);
    % Nhãn chiều cao
    \draw[<-] (C) -- ($(C)!0.5!(H)$) node[midway, right] {$h$};

    % Vẽ các cung góc

    \node at ($(A)+(0.6,0.15)$) {$8^{\circ}$};


    \node at ($(B)+(-1.9,0.15)$) {$4^{\circ}$};

\end{tikzpicture}
}
\loigiai{  
 Ta có: $AH=h \cdot \cot{4^{\circ}}$, $BH=h \cdot \cot{8^{\circ}}$

 $AB=AH+BH=h \cdot \cot{4^{\circ}} + h \cdot \cot{8^{\circ}} = h \left(\cot{4^{\circ}} +\cot{8^{\circ}} \right)$

 $h= \dfrac{1,0}{ \cot{4^{\circ}} +  \cot{8^{\circ}}} \approx 0,0467km \approx 47m$ 
 }\end{ex}

