\choice
{ $\widehat{M}= 90^{\circ}, \widehat{B}= 14^{\circ}, \widehat{A}= 76^{\circ}$  }
   { $\widehat{M}= 90^{\circ}, \widehat{B}= 17^{\circ}, \widehat{A}= 73^{\circ}$  }
     { \True $\widehat{M}= 90^{\circ}, \widehat{B}= 15^{\circ}, \widehat{A}= 75^{\circ}$  }
