L09_C5_B2_24.latex:
\begin{ex}%[9H5C2-1]
\immini[thm]{
Cho tam giác ${ABC}$ vuông tại ${A}$ biết $\widehat{B}=4\widehat{C}$. Đường tròn ${(O)}$ tiếp xúc với cả ba cạnh ${BC,CA, AB}$ của tam giác ${ABC}$ lần lượt tại ${D, E, F}$. Tính $sd\stackrel\frown{EF}:sd\stackrel\frown{DF}:sd\stackrel\frown{DE}$\\ 

\choice
{ $5:7:9$  }
   { $6:6:9$  }
     { \True  $5:6:9$ }
    { $7:6:9$  }
}{
\begin{tikzpicture}
    % Vẽ lưới

    % Định nghĩa các điểm A, B, C, O, D, E, F
    \coordinate [label=below left:{$A$}] (a) at (-2,-3); 
    \coordinate [label=below right:{$B$}] (b) at (2,-3); 
    \coordinate [label=above left:{$C$}] (c) at (-2,3); 
    \coordinate [label=above left:{$O$}] (o) at (-0.61,-1.61); 
    \coordinate [label=above left:{$F$}] (f) at (-2,-1.61); 
    \coordinate [label=above right:{$D$}] (d) at (0.55,-0.83); 
    \coordinate [label=below:{$E$}] (e) at (-0.61,-3); 

    % Vẽ tam giác ABC
    \draw[thick] (a)--(b)--(c)--cycle; 

    % Vẽ các điểm
    \fill (a) circle (1.2pt); % Đánh dấu điểm A
    \fill (b) circle (1.2pt); % Đánh dấu điểm B
    \fill (c) circle (1.2pt); % Đánh dấu điểm C
    \fill (o) circle (1.2pt); % Đánh dấu điểm O
    \fill (f) circle (1.2pt); % Đánh dấu điểm F
    \fill (d) circle (1.2pt); % Đánh dấu điểm D
    \fill (e) circle (1.2pt); % Đánh dấu điểm E

    % Vẽ đường tròn nội tiếp tam giác ABC
    \draw [black] (o) circle [radius=1.39cm]; 
    \def\khvuong[size=#1](#2,#3,#4){%
        \draw ($(#3)!#1!(#2)$) --
        ($($(#3)!#1!(#2)$)+($(#3)!#1!(#4)$)-(#3)$)--
        ($(#3)!#1!(#4)$);
    }
    \khvuong[size=5pt](c,a,b);%
    \end{tikzpicture}
}
\loigiai{ 
 Ta có $\widehat{B}+\widehat{C} =90^{\circ}$ hay $4\widehat{C}+\widehat{C} =90^{\circ}$ suy ra $\widehat{C}=18^{\circ}$ suy ra $\widehat{DOE}=162^{\circ}$ suy ra $sd\stackrel\frown{DE}=162^{\circ}$

  $\widehat{B}=4\widehat{C}=72^{\circ}$ suy ra $\widehat{DOF}=108^{\circ}$ suy ra $sd\stackrel\frown{DF}=108^{\circ}$

  Ta có $\widehat{EOF}=90^{\circ}$ nên $sd\stackrel\frown{EF}=90^{\circ}$ 

 Vậy $sd\stackrel\frown{EF}:sd\stackrel\frown{DF}:sd\stackrel\frown{DE}= 5:6:9$ 
 }\end{ex}

